NSString* NFBEmbeddedString(NSString* key) {
    if (key.length == 0) { return nil; }
    NSString* lang = @"en";
    for (NSString* preferred in [NSLocale preferredLanguages]) {
        NSString* lower = preferred.lowercaseString;
        if ([lower hasPrefix:@"zh-hant"] || [lower hasPrefix:@"zh-tw"] || [lower hasPrefix:@"zh-hk"]) { lang = @"zh-Hant"; }
        else if ([lower hasPrefix:@"zh"]) { lang = @"zh_CN"; }
        else if ([lower hasPrefix:@"ja"]) { lang = @"ja"; }
        else if ([lower hasPrefix:@"ko"]) { lang = @"ko"; }
        else if ([lower hasPrefix:@"ru"]) { lang = @"ru"; }
        else if ([lower hasPrefix:@"fr"]) { lang = @"fr"; }
        else if ([lower hasPrefix:@"de"]) { lang = @"de"; }
        else if ([lower hasPrefix:@"es"]) { lang = @"es"; }
        else if ([lower hasPrefix:@"tr"]) { lang = @"tr"; }
        else if ([lower hasPrefix:@"uk"]) { lang = @"uk"; }
        else if ([lower hasPrefix:@"pl"]) { lang = @"pl"; }
        else if ([lower hasPrefix:@"sv"]) { lang = @"sv"; }
        else if ([lower hasPrefix:@"id"]) { lang = @"id"; }
        else if ([lower hasPrefix:@"hr"]) { lang = @"hr"; }
        else if ([lower hasPrefix:@"ar"]) { lang = @"ar"; }
        break;
    }
    if ([lang isEqualToString:@"zh_CN"]) { NSString* v = NFBTable_zh_CN()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"zh-Hant"]) { NSString* v = NFBTable_zh_Hant()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"en"]) { NSString* v = NFBTable_en()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"ja"]) { NSString* v = NFBTable_ja()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"ko"]) { NSString* v = NFBTable_ko()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"ru"]) { NSString* v = NFBTable_ru()[key]; if (v.length) { return v; } }
    if ([lang isEqualToString:@"fr"]) { NSString* v = NFBTable_fr()[key]; if (v.length) { return v; } }
